472|     /**
473|      * Reads the central directory of the given archive and populates
474|      * the internal tables with ZipArchiveEntry instances.
475|      *
476|      * <p>The ZipArchiveEntrys will know all data that can be obtained from
477|      * the central directory alone, but not the data that requires the
478|      * local file header or additional data to be read.</p>
479|      *
480|      * @return a map of zipentries that didn't have the language
481|      * encoding flag set when read.
482|      */
483|     private Map<ZipArchiveEntry, NameAndComment> populateFromCentralDirectory()
484|         throws IOException {
485|         HashMap<ZipArchiveEntry, NameAndComment> noUTF8Flag =
486|             new HashMap<ZipArchiveEntry, NameAndComment>();
487| 
488|         positionAtCentralDirectory();
489| 
490|         archive.readFully(WORD_BUF);
491|         long sig = ZipLong.getValue(WORD_BUF);
492| 
493|         if (sig != CFH_SIG && startsWithLocalFileHeader()) {
494|             throw new IOException("central directory is empty, can't expand"
495|                                   + " corrupt archive.");
496|         }
497| 
498|         while (sig == CFH_SIG) {
499|             readCentralDirectoryEntry(noUTF8Flag);
500|             archive.readFully(WORD_BUF);
501|             sig = ZipLong.getValue(WORD_BUF);
502|         }
503|         return noUTF8Flag;
504|     }
505| 
506|     /**
507|      * Reads an individual entry of the central directory, creats an
508|      * ZipArchiveEntry from it and adds it to the global maps.
509|      *
510|      * @param noUTF8Flag map used to collect entries that don't have
511|      * their UTF-8 flag set and whose name will be set by data read
512|      * from the local file header later.  The current entry may be
513|      * added to this map.
514|      */
515|     private void
516|         readCentralDirectoryEntry(Map<ZipArchiveEntry, NameAndComment> noUTF8Flag)
517|         throws IOException {
518|         archive.readFully(CFH_BUF);
519|         int off = 0;
520|         OffsetEntry offset = new OffsetEntry();
521|         Entry ze = new Entry(offset);
522| 
523|         int versionMadeBy = ZipShort.getValue(CFH_BUF, off);
524|         off += SHORT;
525|         ze.setPlatform((versionMadeBy >> BYTE_SHIFT) & NIBLET_MASK);
526| 
527|         off += SHORT; // skip version info
528| 
529|         final GeneralPurposeBit gpFlag = GeneralPurposeBit.parse(CFH_BUF, off);
530|         final boolean hasUTF8Flag = gpFlag.usesUTF8ForNames();
531|         final ZipEncoding entryEncoding =
532|             hasUTF8Flag ? ZipEncodingHelper.UTF8_ZIP_ENCODING : zipEncoding;
533|         ze.setGeneralPurposeBit(gpFlag);
534| 
535|         off += SHORT;
536| 
537|         ze.setMethod(ZipShort.getValue(CFH_BUF, off));
538|         off += SHORT;
539|

544|         ze.setCrc(ZipLong.getValue(CFH_BUF, off));
545|         off += WORD;
546| 
547|         ze.setCompressedSize(ZipLong.getValue(CFH_BUF, off));
548|         off += WORD;
549| 
550|         ze.setSize(ZipLong.getValue(CFH_BUF, off));
551|         off += WORD;
552| 
553|         int fileNameLen = ZipShort.getValue(CFH_BUF, off);
554|         off += SHORT;
555| 
556|         int extraLen = ZipShort.getValue(CFH_BUF, off);
557|         off += SHORT;
558| 
559|         int commentLen = ZipShort.getValue(CFH_BUF, off);
560|         off += SHORT;
561| 
562|         int diskStart = ZipShort.getValue(CFH_BUF, off);
563|         off += SHORT;
564| 
565|         ze.setInternalAttributes(ZipShort.getValue(CFH_BUF, off));
566|         off += SHORT;
567| 
568|         ze.setExternalAttributes(ZipLong.getValue(CFH_BUF, off));
569|         off += WORD;
570| 
571|         byte[] fileName = new byte[fileNameLen];
572|         archive.readFully(fileName);
573|         ze.setName(entryEncoding.decode(fileName), fileName);
574| 
575|         // LFH offset,
576|         offset.headerOffset = ZipLong.getValue(CFH_BUF, off);
577|         // data offset will be filled later
578|         entries.add(ze);
579| 
580|         byte[] cdExtraData = new byte[extraLen];
581|         archive.readFully(cdExtraData);
582|         ze.setCentralDirectoryExtra(cdExtraData);
583| 
584|         setSizesAndOffsetFromZip64Extra(ze, offset, diskStart);
585| 
586|         byte[] comment = new byte[commentLen];
587|         archive.readFully(comment);
588|         ze.setComment(entryEncoding.decode(comment));
589| 
590|         if (!hasUTF8Flag && useUnicodeExtraFields) {
591|             noUTF8Flag.put(ze, new NameAndComment(fileName, comment));
592|         }
593|     }
