595|     /**
596|      * If the entry holds a Zip64 extended information extra field,
597|      * read sizes from there if the entry's sizes are set to
598|      * 0xFFFFFFFFF, do the same for the offset of the local file
599|      * header.
600|      *
601|      * <p>Ensures the Zip64 extra either knows both compressed and
602|      * uncompressed size or neither of both as the internal logic in
603|      * ExtraFieldUtils forces the field to create local header data
604|      * even if they are never used - and here a field with only one
605|      * size would be invalid.</p>
606|      */
607|     private void setSizesAndOffsetFromZip64Extra(ZipArchiveEntry ze,
608|                                                  OffsetEntry offset,
609|                                                  int diskStart)
610|         throws IOException {
611|         Zip64ExtendedInformationExtraField z64 =
612|             (Zip64ExtendedInformationExtraField)
613|             ze.getExtraField(Zip64ExtendedInformationExtraField.HEADER_ID);
614|         if (z64 != null) {
615|             boolean hasUncompressedSize = ze.getSize() == ZIP64_MAGIC;
616|             boolean hasCompressedSize = ze.getCompressedSize() == ZIP64_MAGIC;
617|             boolean hasRelativeHeaderOffset =
618|                 offset.headerOffset == ZIP64_MAGIC;
619|             z64.reparseCentralDirectoryData(hasUncompressedSize,
620|                                             hasCompressedSize,
621|                                             hasRelativeHeaderOffset,
622|                                             diskStart == ZIP64_MAGIC_SHORT);
623| 
624|             if (hasUncompressedSize) {
625|                 ze.setSize(z64.getSize().getLongValue());
626|             } else if (hasCompressedSize) {
627|                 z64.setSize(new ZipEightByteInteger(ze.getSize()));
628|             }
629| 
630|             if (hasCompressedSize) {
631|                 ze.setCompressedSize(z64.getCompressedSize().getLongValue());
632|             } else if (hasUncompressedSize) {
633|                 z64.setCompressedSize(new ZipEightByteInteger(ze.getCompressedSize()));
634|             }
635| 
636|             if (hasRelativeHeaderOffset) {
637|                 offset.headerOffset =
638|                     z64.getRelativeHeaderOffset().getLongValue();
639|             }
640|         }
641|     }
